class Solution:
    def maximalPathQuality(self, values: List[int], edges: List[List[int]], maxTime: int) -> int:
        n = len(values)
        adj = [[] for _ in range(n)]
        for u, v, t in edges:
            adj[u].append((v, t))
            adj[v].append((u, t))
        seen = [False] * n
        seen[0] = True
        ans = 0

        def dfs(u, time, quality):
            nonlocal ans
            if u == 0:
                ans = max(ans, quality)
            for v, t in adj[u]:
                nt = time + t
                if nt > maxTime:
                    continue
                first = not seen[v]
                if first:
                    seen[v] = True
                dfs(v, nt, quality + (values[v] if first else 0))
                if first:
                    seen[v] = False

        dfs(0, 0, values[0])
        return ans

